style.css:
@-moz-document domain("roblox.com") {
html, body, * {
    background: none !important;
    background-color: transparent !important;
    color: white !important;
  }

  body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    height: 100vh;
    width: 100vw;
    z-index: -9999;
    background-image: url("https://i.imgur.com/MxujSg1.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    opacity: 1;
  }

  /* Optional: make panels darker and rounded */
  .game-card, .container, .section, .content, .rbx-header, .footer {
    background-color: rgba(0, 0, 0, 0.6) !important;
    border-radius: 10px !important;
  }

  /* Fix text visibility */
  .text-label, .text-overflow, .section-header, h1, h2, h3, p, span, div {
    color: #ffffff !important;
  }
}
